}

List<AssistantMessageEvent> _readTurn(int n) => toolTurn([
  ToolCall(id: 't$n', name: 'read', arguments: {'path': 'note.txt'}),
]);

AgentCli _bootCli({
  required MemoryExecutionEnv env,
