    io = FakeCliIO();
  });

  tearDown(() {
    io.close();
    tempHome.deleteSync(recursive: true);
  });

  group('gh-1680 message-cap repair through the real CLI', () {
    test(
      'learned-cap refusal heals: persist, compact via relief, retry once',
      timeout: const Timeout(Duration(seconds: 120)),
      () async {
