        // trips shouldCompact).
        Directory('${tempHome.path}/.fah').createSync(recursive: true);
        File('${tempHome.path}/.fah/model_caps.json').writeAsStringSync(
          jsonEncode({
            ModelCapsStore.keyOf('test-provider', 'cap-model'): {
              'maxMessages': 24,
            },
          }),
