  const quietSmall = [3.4, 3.31, 3.35, 3.3, 3.42, 3.4, 3.38, 3.33, 3.4];
  const pausedDoubled = [6.8, 7.0, 12.09, 12.2, 11.9, 7.1, 6.9, 7.2, 7.0];
