        expect(
          turnMessages,
          lessThan(9),
          reason: 'the pre-emptive boot cap must shrink the transcript',
        );
        // The pass report is the visible receipt of the boot cap.
        expect(io.out.toString(), contains('auto-compacted'));
      },
    );

