/// backstop exists for (the compaction itself landed; only the report
/// render crashes).
class _BrokenStdoutIo extends FakeCliIO {
  @override
  void writeln(String text) {
    if (text.contains('auto-compacted')) {
      throw StateError('stdout pipe broken');
    }
    super.writeln(text);
  }
}

