    // clean, and only THIS run's folds may badge it (issue #438 E1).
    _autoFoldCount = 0;
    // One empty-reply nudge per logical turn (issue #1085 M2b).
    _emptyReplyNudgesLeft = 1;
    // The stuck-call nudge budget refills per turn (issue #1185 E2).
