/// refusal-heal script, with the final answer reserved for the LAST turn.
class _CapAwareSwitchStream {
 final contexts = <Context>[];
 int get calls => contexts.length;
 int _turnCalls = 0;
 int _chunkCalls = 0;

 AssistantMessageEventStream call(Model model, Context context, {CancelToken? cancelToken}) {
 contexts.add(Context(systemPrompt: context.systemPrompt, messages: List.of(context.messages), tools: context.tools));
 final List<AssistantMessageEvent> events;
 if (context.messages.length <= 1) {
  events = textTurn('compacted pre-flight summary chunk ${++_chunkCalls}');
 } else {
   _turnCalls++;
   events = switch (_turnCalls) {
     1 => _capUnknownRefusalTurn(),
     2 => textTurn('ok after coalesce'),
     _ => textTurn('FINAL ANSWER on the compacted transcript'),
   };
 }
 final stream = AssistantMessageEventStream();
 for (final event in events) {
   stream.push(event);
 }
 stream.end();
 return stream;
 }
