 AssistantMessageEventStream call(Model model, Context context, {CancelToken? cancelToken}) {
 contexts.add(Context(systemPrompt: context.systemPrompt, messages: List.of(context.messages), tools: context.tools));
 final List<AssistantMessageEvent> events;
