     1 => _capUnknownRefusalTurn(),
     2 => textTurn('ok after coalesce'),
     _ => textTurn('FINAL ANSWER on the compacted transcript'),
   };
 }
 final stream = AssistantMessageEventStream();
 for (final event in events) {
   stream.push(event);
 }
 stream.end();
 return stream;
 }
