  Future<void> settle(bool Function() condition, {String? reason}) async {
    for (var i = 0; i < 300; i++) {
      if (condition()) return;
      await Future<void>.delayed(const Duration(milliseconds: 100));
    }
    fail('timed out waiting for the CLI to settle: ${reason ?? 'condition'}');
  }
}

