            .lookup(model.provider, model.id)
            ?.messageCap,
      );

  @override
  void learnFromRefusal(Model model, MessageCapRefusal refusal) {
    _cli._modelCaps.learnFromRefusal(model, refusal);
    _cli._persistModelCaps();
  }
}

