    } finally {
      _pushBusyPhase('');
    }
    final after = _agent.state.messages.toList();
    if (after.length >= beforeCount) {
      _logDiagnostic('message-cap relief no-op sid=$_logSid');
      return null;
    }
    _logDiagnostic(
      'message-cap relief done sid=$_logSid messages=${after.length} '
      '(was $beforeCount)',
    );
    io.writeln(
